#if canImport(UIKit)
import UIKit

public enum EarthTextureProvider {
    public static func loadTexture() -> UIImage? {
        if let path = Bundle.main.path(forResource: "earth_paper_texture", ofType: "png"), let img = UIImage(contentsOfFile: path) { return img }
        if let img = UIImage(named: "earth_paper_texture") { return img }
        if let data = Data(base64Encoded: "") { return UIImage(data: data) }
        return nil
    }
}
#endif
